_BOOTSTRAP_SHA256 = "d8fafdf0b88a8917e741b42296414c26d992056ca15b35da745a5d4257190ef6"


def _teardown(undo, *not_found: str):
    """A cleanup running ``undo()`` where a failed delete raises; only ``not_found`` means gone."""

    def run_undo() -> None:
        try:
            undo()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in not_found:
                return
            raise

    return run_undo


def _budget_s(ctx, cap_s):
    """A poll's timeout: cap_s, bounded by the runner's remaining time less 5 s so the poll fails
    with its own message."""
    left = ctx.time_left()
    return cap_s if left is None else max(1.0, min(cap_s, left - 5.0))


def _budget_spent(ctx):
    """True when the runner's remaining time, not the wait's own deadline, ended a capped wait."""
    left = ctx.time_left()
    return left is not None and left <= 6.0


def _poll(ctx, probe, done, *, timeout_s, interval_s=2.0, what):
    """``probe()`` until ``done(result)``; raises naming ``what`` and the last result on timeout."""
    deadline = time.monotonic() + _budget_s(ctx, timeout_s)
    last = None
    while True:
        last = probe()
        if done(last):
            return last
        if time.monotonic() >= deadline:
            break
        time.sleep(interval_s)
    if _budget_spent(ctx):
        raise TimeoutError(f"{what}: the run budget ended first; not graded")
    raise AssertionError(f"timed out after {timeout_s}s waiting until {what}; last={last!r}")


def _xname(ctx, kind: str) -> str:
    return ctx.unique_name(f"sim2real-xsvc-{kind}-")


def _bootstrap_binary() -> bytes:
    """Decompress the embedded Go bootstrap and verify it is exactly what was authored."""
    raw_bytes = gzip.decompress(base64.b64decode(_BOOTSTRAP_GZ_B64))
    got = hashlib.sha256(raw_bytes).hexdigest()
    assert got == _BOOTSTRAP_SHA256, f"embedded bootstrap sha256 {got!r} != {_BOOTSTRAP_SHA256!r}"
    return raw_bytes


def _zip_bootstrap(binary: bytes) -> bytes:
    """A deployment zip with ``bootstrap`` marked executable, as provided.al2023 requires."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        info = zipfile.ZipInfo("bootstrap")
        info.external_attr = 0o755 << 16
        zf.writestr(info, binary)
    return buf.getvalue()


def _create_role(ctx, statements) -> dict:
    """A Lambda execution role trusting lambda.amazonaws.com, holding exactly ``statements``."""
    iam = ctx.client("iam")
    name = _xname(ctx, "role")
    trust = {"Version": "2012-10-17", "Statement": [{
        "Effect": "Allow", "Principal": {"Service": "lambda.amazonaws.com"},
        "Action": "sts:AssumeRole"}]}
    role = iam.create_role(RoleName=name, AssumeRolePolicyDocument=json.dumps(trust),
                            Tags=[{"Key": "sim2real", "Value": CHECK}])["Role"]
    ctx.on_cleanup(_teardown(lambda: iam.delete_role(RoleName=name), "NoSuchEntity"))
    if statements:
        iam.put_role_policy(RoleName=name, PolicyName="sim2real-inline", PolicyDocument=json.dumps(
            {"Version": "2012-10-17", "Statement": statements}))
        ctx.on_cleanup(_teardown(
            lambda: iam.delete_role_policy(RoleName=name, PolicyName="sim2real-inline"),
            "NoSuchEntity"))
    return {"name": name, "arn": role["Arn"]}


def _create_function(ctx, role_arn, name, *, mode, env=None, timeout=10, memory=256,
                      arch="x86_64") -> dict:
    """A provided.al2023 function running the embedded Go bootstrap, through the
    role-propagation window and to Active."""
    lam = ctx.client("lambda")
    binary = _bootstrap_binary()
    full_env = {"CHECK_MODE": mode}
    if env:
        full_env.update(env)
    kwargs = {
        "FunctionName": name, "Runtime": "provided.al2023", "Handler": "bootstrap",
        "Role": role_arn, "Code": {"ZipFile": _zip_bootstrap(binary)},
        "Architectures": [arch], "Timeout": timeout, "MemorySize": memory,
        "Environment": {"Variables": full_env}, "Tags": {"sim2real": CHECK},
    }

    def create():
        try:
            return lam.create_function(**kwargs)
        except ClientError as exc:
            err = exc.response["Error"]
            if (err["Code"] == "InvalidParameterValueException"
                    and "cannot be assumed" in err.get("Message", "")):
                return None
            raise

    out = _poll(ctx, create, lambda r: r is not None, timeout_s=90,
                what="CreateFunction accepts the fresh execution role")
    ctx.on_cleanup(_teardown(lambda: lam.delete_function(FunctionName=name),
                             "ResourceNotFoundException"))
    conf = _poll(ctx, lambda: lam.get_function_configuration(FunctionName=name),
                 lambda c: c.get("State", "Active") in ("Active", "Failed"),
                 timeout_s=90, what=f"function {name} leaves Pending")
    assert conf.get("State", "Active") == "Active", (
        f"function {name} ended {conf.get('State')!r}: {conf.get('StateReason')!r}")
    return {"name": name, "arn": out["FunctionArn"]}


def _ssl_context(verify):
    """An SSLContext honouring ``ctx.http_verify``: True, False, or a CA bundle path."""
    if verify is False:
        return ssl._create_unverified_context()
    return ssl.create_default_context(cafile=verify if isinstance(verify, str) else None)


def _http(method, url, verify, body=None, headers=None):
    """HTTP request via urllib (stdlib only). Returns (status, lower-cased headers, text)."""
    req = urllib.request.Request(url, data=body, method=method, headers=headers or {})
    try:
        with urllib.request.urlopen(req, context=_ssl_context(verify)) as resp:  # noqa: S310 - fixed http(s) scheme
            return (resp.status, {k.lower(): v for k, v in resp.headers.items()},
                    resp.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as e:
        return (e.code, {k.lower(): v for k, v in e.headers.items()},
                e.read().decode("utf-8", "replace"))


def _poll_http(ctx, url, *, accept, verify, headers=None, timeout_s=150.0, interval_s=2.0,
                what="invoke url"):
    """Poll an invoke URL until accept(status); execute-api DNS/TLS settling retries, not raises."""
    deadline = time.monotonic() + _budget_s(ctx, timeout_s)
    last = (None, {}, "")
    while True:
        try:
            last = _http("GET", url, verify, headers=headers)
        except Exception:
            last = (None, {}, "connection error")
        else:
            if accept(last[0]):
                return last
        if time.monotonic() >= deadline:
            break
        time.sleep(interval_s)
    if _budget_spent(ctx):
        raise TimeoutError(f"{what}: the run budget ended first; not graded")
    raise AssertionError(f"{what} never reached an accepted status within {timeout_s}s: {last!r}")


@tags("axis:happy-path", "cap:c3", "concern:data-plane", "concern:e2e", "concern:representation",
      "dp:endpoint", "plane:data")
def run(ctx) -> None:
    """A Go handler's Lambda proxy response (statusCode, a custom header, a JSON body) shapes the
    HTTP response API Gateway returns, and the method, path, a query parameter and a header from
    the real HTTP request reach the handler through the proxy event untouched.

    Reference: https://docs.aws.amazon.com/apigateway/latest/developerguide/set-up-lambda-proxy-integrations.html
    """
    role = _create_role(ctx, [])
    fn = _create_function(ctx, role["arn"], _xname(ctx, "fn"), mode="apigw_proxy", timeout=10)

    ag = ctx.client("apigateway")
    api_id = ag.create_rest_api(name=_xname(ctx, "api"),
                                endpointConfiguration={"types": ["REGIONAL"]})["id"]
    ctx.on_cleanup(_teardown(lambda: ag.delete_rest_api(restApiId=api_id), "NotFoundException"))
    root_id = next(r["id"] for r in ag.get_resources(restApiId=api_id)["items"] if r["path"] == "/")
    proxy_id = ag.create_resource(restApiId=api_id, parentId=root_id, pathPart="{proxy+}")["id"]
    ag.put_method(restApiId=api_id, resourceId=proxy_id, httpMethod="ANY", authorizationType="NONE")
    ag.put_integration(
        restApiId=api_id, resourceId=proxy_id, httpMethod="ANY", type="AWS_PROXY",
        integrationHttpMethod="POST",
        uri=(f"arn:aws:apigateway:{ctx.region}:lambda:path/2015-03-31/functions/"
             f"{fn['arn']}/invocations"))

    ctx.client("lambda").add_permission(
        FunctionName=fn["name"], StatementId="apigw-invoke", Action="lambda:InvokeFunction",
        Principal="apigateway.amazonaws.com",
        SourceArn=f"arn:aws:execute-api:{ctx.region}:{ctx.account}:{api_id}/*/*")

    stage = "test"
    ag.create_deployment(restApiId=api_id, stageName=stage)

    url = f"{ctx.rest_api_url(api_id, stage)}/items/42?status=201"
    marker = ctx.unique_name("echo")
    status, headers, body = _poll_http(ctx, url, headers={"x-sim2real-echo": marker},
                                       accept=lambda s: s == 201, verify=ctx.http_verify,
                                       what="REST API GET /items/42")
    assert status == 201, (
        f"handler-chosen statusCode 201 did not reach the client; got {status}: {body[:300]!r}")
    assert headers.get("x-sim2real-handler") == "go-provided-al2023", (
        f"the handler's custom response header did not reach the client; headers={headers!r}")
    payload = json.loads(body)
    assert payload["receivedMethod"] == "GET", payload
    assert payload["receivedPath"] == "/items/42", payload
    assert payload["receivedQuery"] == {"status": "201"}, payload
    assert payload["receivedEchoHdr"] == marker, payload


if __name__ == "__main__":
    from fidelity_tests_runner import main
    main(run)
